INSERT INTO `travel_logs` VALUES (1,2,NULL,1,'甲子钟广场拍照路线','从沙河校区图书馆出发走到甲子钟广场，下午光线比较适合拍照。',4.8,NULL,NULL,NULL,NULL,NULL,321,321,1,0,'2026-05-08 10:00:00','2026-05-10 15:21:14'),(2,2,NULL,3,'北区食堂低预算午餐','麻辣香锅适合多人拼，牛肉拉面适合赶时间。',4.5,NULL,NULL,NULL,NULL,NULL,210,210,0,1,'2026-05-08 11:30:00','2026-05-08 19:46:26'),(3,3,8,2,'奥森周末骑行','适合从学校出发做半日城市自然路线。',4.9,NULL,NULL,NULL,NULL,NULL,450,450,1,1,'2026-05-07 18:20:00','2026-05-08 19:46:26'),(4,3,6,2,'通信主题博物馆参观','邮票博物馆和专业背景有关，适合作为城市拓展点。',4.6,NULL,NULL,NULL,NULL,NULL,160,160,0,1,'2026-05-06 15:00:00','2026-05-10 05:01:06'),(5,6,268,1,'按时','aaa',0.0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,'2026-05-10 00:16:04','2026-05-10 15:21:17'),(6,8,NULL,NULL,'接口联调测试游记','用于验证游记写入链路。',4.5,NULL,NULL,NULL,NULL,NULL,3,0,0,1,'2026-05-10 02:20:30','2026-05-10 02:20:30'),(7,8,NULL,1,'圈子接口测试','用于验证圈子日志写入链路。',4.0,NULL,NULL,NULL,NULL,NULL,0,0,0,1,'2026-05-10 02:20:30','2026-05-10 02:20:30'),(8,1,NULL,1,NULL,'测试',0.0,NULL,NULL,NULL,NULL,NULL,0,0,0,1,'2026-05-10 05:38:51','2026-05-10 05:38:51'),(9,1,NULL,NULL,'测试景点日记','测试景点日记',2.0,NULL,NULL,NULL,NULL,NULL,0,0,0,1,'2026-05-10 05:39:59','2026-05-10 05:39:59'),(10,1,NULL,NULL,'Codex无评分验证','这是一条不带评分的验证日志，不应影响景点平均分。',NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,'2026-05-10 13:18:34','2026-05-10 13:18:34'),(11,1,NULL,NULL,'Codex多维评分验证','这是一条带多维评分的验证日志。',4.6,5.0,4.0,5.0,4.0,5.0,0,0,0,0,'2026-05-10 13:18:34','2026-05-10 13:18:34'),(12,1,NULL,NULL,'Codex无评分复测','无评分日记复测。',NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,'2026-05-10 13:20:23','2026-05-10 13:20:23'),(13,1,NULL,3,'测试','测试',NULL,NULL,NULL,NULL,NULL,NULL,1,0,0,1,'2026-05-10 13:30:40','2026-05-10 13:30:53'),(14,1,NULL,1,'测试关联景点','测试关联景点',NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,'2026-05-10 15:21:47','2026-05-10 15:21:52'),(15,1,NULL,1,'测试关联景点','测试关联景点',3.0,NULL,NULL,NULL,NULL,NULL,0,0,0,0,'2026-05-10 15:22:28','2026-05-10 15:47:23'),(16,1,NULL,1,'很好','很好',NULL,NULL,NULL,NULL,NULL,NULL,1,0,0,1,'2026-05-10 15:52:58','2026-05-10 15:53:27'),(17,1,NULL,1,'测试','测试',3.0,NULL,NULL,NULL,NULL,NULL,2,0,0,1,'2026-05-10 16:15:45','2026-05-10 16:15:51');
